// La guía de prueba manual del tester: una tarjeta por criterio de la historia.
const TIER = {
  RUNTIME: { tier: 'run', badge: 'verificado corriendo' },
  'NOT-RUN': { tier: 'pend', badge: 'pendiente' },
};

function renderCard(c) {
  return `<section class="ac" data-ac="${c.n}">
    <header>
      <span class="acnum">AC #${c.n}</span>
      <span class="badge badge-${c.tier}">${c.badge}</span>
    </header>
    <p class="actext">${c.text}</p>
  </section>`;
}

function buildCard(a, perAc) {
  const t = TIER[(perAc[a.n] || {}).verdict] || TIER['NOT-RUN'];
  return { n: a.n, text: a.text, tier: t.tier, badge: t.badge };
}

function renderHtml(cards) {
  return `<style>.badge-run{background:#0a7d32;color:#fff}</style>${cards.map(renderCard).join('')}`;
}

module.exports = { TIER, buildCard, renderCard, renderHtml };

